const { sortByTransactionId } = require("../utils/sort");
const { addExceptionFlag } = require("./exceptions");

const STATUS_ORDER = { pending: 0, approved: 1, rejected: 2, reversed: 3 };

function isComplianceSender(from) {
  return typeof from === "string" && from.toLowerCase().includes("compliance@");
}

function maxStatus(a, b) {
  const aa = String(a || "pending").toLowerCase();
  const bb = String(b || "pending").toLowerCase();
  return (STATUS_ORDER[bb] ?? -1) > (STATUS_ORDER[aa] ?? -1) ? bb : aa;
}

function reconcileTransactions(parsed) {
  // Base from canonical ledger: last row wins for identical txn id (deterministic file order).
  const byId = new Map();
  for (const row of parsed.ledger) {
    byId.set(row.transaction_id, { ...row });
  }

  // Meetings can adjust owner.
  for (const meeting of parsed.meetings) {
    const target = byId.get(meeting.transaction_id);
    if (target && meeting.owner) target.owner = meeting.owner;
  }

  // Compliance emails can update status; apply with precedence (do not let a lower status downgrade).
  for (const email of parsed.emails) {
    if (!isComplianceSender(email.from)) continue;
    const target = byId.get(email.transaction_id);
    if (target && email.status) {
      target.status = maxStatus(target.status, email.status);
    }
  }

  // Build output items.
  const items = sortByTransactionId(
    [...byId.values()].map((row) => ({
      transaction_id: row.transaction_id,
      owner: row.owner,
      status: String(row.status).toLowerCase(),
      effective_date: row.date,
      amount_usd: Number(Number(row.amount).toFixed(2)),
      exception_reason: null,
    }))
  );

  const outById = new Map(items.map((r) => [r.transaction_id, r]));

  // Policy exceptions: flag rows.
  if (parsed.policyExceptions && parsed.policyExceptions.forEach) {
    parsed.policyExceptions.forEach((txnId) => {
      const row = outById.get(txnId);
      if (row) addExceptionFlag(row, "policy_exception");
    });
  }

  // Corrections: pick a winning correction per (transaction_id, field): latest effective, tie-break notice_id.
  const correctionByKey = new Map();
  for (const n of parsed.corrections || []) {
    if (!n || !n.notice_id || !n.transaction_id || !n.field) continue;
    const key = `${n.transaction_id}::${n.field}`;
    const prev = correctionByKey.get(key);
    if (!prev) {
      correctionByKey.set(key, n);
      continue;
    }
    const a = String(prev.effective || "");
    const b = String(n.effective || "");
    if (b > a || (b === a && String(n.notice_id) > String(prev.notice_id))) {
      correctionByKey.set(key, n);
    }
  }

  // Apply winning corrections in notice_id order and produce report with previous_value.
  const winners = [...correctionByKey.values()].sort((x, y) =>
    String(x.notice_id).localeCompare(String(y.notice_id))
  );

  const report = [];
  for (const notice of winners) {
    const row = outById.get(notice.transaction_id);
    if (!row) continue;

    let field = notice.field;
    if (field === "date") field = "effective_date";

    const previous_value = row[field] == null ? "" : String(row[field]);

    // Apply.
    if (field === "owner") row.owner = notice.value;
    else if (field === "status") row.status = String(notice.value).toLowerCase();
    else if (field === "effective_date") row.effective_date = notice.value;

    report.push({
      notice_id: notice.notice_id,
      transaction_id: notice.transaction_id,
      field: notice.field,
      previous_value,
      new_value: String(notice.value),
      effective: notice.effective,
    });
  }

  // Ensure exceptions are null not empty string.
  for (const row of items) {
    if (!row.exception_reason) row.exception_reason = null;
  }

  // Contract: report sorted by notice_id ascending.
  report.sort((a, b) => String(a.notice_id).localeCompare(String(b.notice_id)));

  return { items, report };
}

module.exports = { reconcileTransactions, STATUS_ORDER };
